"use client";

import { motion, useReducedMotion } from "framer-motion";

const ORBITS = [
  { radius: 0.38, dot: 0.11, color: "rgb(5 150 105)", glow: "rgba(5,150,105,0.6)", duration: 1.6, from: 0, to: 360 },
  { radius: 0.49, dot: 0.075, color: "rgb(110 231 183)", glow: "rgba(110,231,183,0.55)", duration: 2.4, from: 200, to: -160 },
] as const;

export function OrbitLoader({
  icon,
  size = 56,
  label = "Loading",
}: {
  icon?: React.ReactNode;
  size?: number;
  label?: string;
}) {
  const shouldReduceMotion = useReducedMotion();
  const medallionSize = size * 0.42;

  return (
    <div
      role="status"
      aria-label={label}
      className="relative inline-flex items-center justify-center"
      style={{ width: size, height: size }}
    >
      {/* guide rings: a faint track for each dot, so the motion reads as an orbit, not floating specks */}
      {ORBITS.map((orbit, i) => (
        <span
          key={`track-${i}`}
          aria-hidden
          className="absolute rounded-full border border-emerald-400/15"
          style={{
            width: size * orbit.radius * 2,
            height: size * orbit.radius * 2,
            top: "50%",
            left: "50%",
            transform: "translate(-50%, -50%)",
          }}
        />
      ))}

      {ORBITS.map((orbit, i) => {
        const dotSize = Math.max(2, size * orbit.dot);
        return (
          <motion.span
            key={`orbit-${i}`}
            aria-hidden
            className="absolute inset-0"
            initial={{ rotate: orbit.from }}
            animate={
              shouldReduceMotion ? { rotate: orbit.from, opacity: [0.4, 1, 0.4] } : { rotate: orbit.to }
            }
            transition={
              shouldReduceMotion
                ? { duration: 1.6, repeat: Infinity, ease: "easeInOut", delay: i * 0.25 }
                : { duration: orbit.duration, repeat: Infinity, ease: "linear" }
            }
          >
            <span
              className="absolute rounded-full"
              style={{
                width: dotSize,
                height: dotSize,
                top: "50%",
                left: "50%",
                background: orbit.color,
                boxShadow: `0 0 4px ${orbit.glow}`,
                transform: `translate(calc(-50% + ${size * orbit.radius}px), -50%)`,
              }}
            />
          </motion.span>
        );
      })}

      <div
        className="relative flex items-center justify-center rounded-full bg-white text-emerald-700 shadow-[0_2px_10px_-2px_rgba(5,150,105,0.35)] dark:bg-neutral-950 dark:text-emerald-400"
        style={{ width: medallionSize, height: medallionSize }}
      >
        <motion.span
          aria-hidden
          className="absolute inset-0 rounded-full bg-emerald-400/25 blur-sm dark:bg-emerald-400/20"
          animate={
            shouldReduceMotion ? { opacity: 0.35 } : { opacity: [0.2, 0.45, 0.2], scale: [0.92, 1.04, 0.92] }
          }
          transition={{ duration: 1.8, repeat: Infinity, ease: "easeInOut" }}
        />
        {/* absolute + inset-0 gives this a definite box to center against (a shrink-to-fit
            span here would leave a percentage-sized SVG child mis-measured and left-anchored) */}
        <span className="absolute inset-0 flex items-center justify-center">
          {icon ?? (
            <svg viewBox="0 0 24 24" width="40%" height="40%" fill="currentColor" aria-hidden>
              <circle cx="12" cy="12" r="6" />
            </svg>
          )}
        </span>
      </div>
    </div>
  );
}
